insert into public.question_translations (question_id, dil, soru, secenekler)
select q.id, 'en', v.en_soru, v.en_secenekler
  from (values
  ('1965''te Mondrian resimlerini elbiselere uyarlayan tasarımcı hangisidir?', 'Which designer adapted Mondrian paintings into dresses in 1965?', '["Saint Laurent","Karl Lagerfeld","Coco Chanel","Christian Dior"]'::jsonb),
